import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.CNIcw2kk.js";var i=JSON.parse(`{"title":"Parity report -- comply against the reuse tool","description":"","frontmatter":{},"headers":[],"relativePath":"parity.md","filePath":"parity.md","lastUpdated":1785542157000}`),a={name:`parity.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="parity-report-comply-against-the-reuse-tool" tabindex="-1">Parity report -- comply against the reuse tool <a class="header-anchor" href="#parity-report-comply-against-the-reuse-tool" aria-label="Permalink to “Parity report -- comply against the reuse tool”">​</a></h1><p>Differential check: comply 0.1.0 vs reuse 6.2.0.</p><p>Both tools run over the comply repository itself. The question is not whether each passes, but whether they say the same thing about the same files.</p><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to “Verdict”">​</a></h2><p><strong>Full agreement on <code>lint</code>.</strong> 109 files seen by both, zero disagreements. comply sees a strict subset of reuse&#39;s file set, and the only difference is its own <code>[tool.comply] ignore</code> config.</p><p><code>annotate</code> is where the two still part company. Nothing recorded below changes a lint verdict -- neither the comment-style tables nor the uncommentable tables are consulted by <code>lint</code> -- but they decide what <code>annotate</code> writes, and they are not identical. See &quot;Uncommentable formats&quot; below.</p><h2 id="where-they-agree" tabindex="-1">Where they agree <a class="header-anchor" href="#where-they-agree" aria-label="Permalink to “Where they agree”">​</a></h2><table tabindex="0"><thead><tr><th>Measure</th><th>Result</th></tr></thead><tbody><tr><td>Files seen by both</td><td>109</td></tr><tr><td>Licence disagreements</td><td>0</td></tr><tr><td>Unused licences (both)</td><td>0</td></tr><tr><td>Files only comply sees</td><td>0</td></tr><tr><td>Exit codes</td><td>0 / 0</td></tr></tbody></table><p>Both report the same three licences in use -- <code>Apache-2.0</code>, <code>CC-BY-3.0</code>, <code>MIT</code> -- and neither finds an unused or missing licence text. Comparing the SPDX identifier set per file across all 109 shared files yields no mismatch.</p><p>The <code>CC-BY-3.0</code> agreement is recent. comply previously reported it unused because <code>DCO.txt</code>, its only carrier, sits in <code>[tool.comply] ignore</code> and was dropped from licence accounting along with the walk. That is now fixed; see <code>collect_declared_by_ignored</code> in <code>commands/lint.rs</code>.</p><h2 id="where-they-differ" tabindex="-1">Where they differ <a class="header-anchor" href="#where-they-differ" aria-label="Permalink to “Where they differ”">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Files</th><th>Verdict</th></tr></thead><tbody><tr><td>By design</td><td>7 -- seen only by reuse</td><td>comply honours <code>[tool.comply] ignore</code>; reuse has no such config.</td></tr><tr><td>Representation</td><td>all shared files</td><td>Same identifiers, different <code>LicenseInfoInFile</code> shape.</td></tr><tr><td>Comment styles</td><td><code>annotate</code> only</td><td>comply claims 19 extensions reuse rejects, and picks a different syntax for <code>.c</code>, <code>.h</code> and <code>.ini</code>. Lint output is unaffected.</td></tr><tr><td>Uncommentable formats</td><td><code>annotate</code> only</td><td>Same contract, different tables. comply writes a companion for 20 formats reuse refuses and refuses 44 reuse writes one for.</td></tr><tr><td>Existing companion</td><td><code>annotate</code> only</td><td>reuse merges the old notice with the new; comply preserves and reports, and <code>--force</code> replaces. Open gap.</td></tr><tr><td>Companion line endings</td><td><code>annotate</code> only</td><td>Identical on binaries. reuse mirrors CRLF for text-decodable files such as <code>.json</code>; comply always writes LF.</td></tr><tr><td><code>fix</code> vs <code>annotate</code></td><td>comply-internal</td><td>Closed. Both now call <code>header::generate</code>, so they emit the same bytes -- see below.</td></tr></tbody></table><h2 id="detail" tabindex="-1">Detail <a class="header-anchor" href="#detail" aria-label="Permalink to “Detail”">​</a></h2><h3 id="by-design-seven-files-only-reuse-sees" tabindex="-1">By design: seven files only reuse sees <a class="header-anchor" href="#by-design-seven-files-only-reuse-sees" aria-label="Permalink to “By design: seven files only reuse sees”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.actrc                      instructions.md</span></span>
<span class="line"><span>Cargo.lock                  mise.lock</span></span>
<span class="line"><span>DCO.txt                     supply-chain/imports.lock</span></span>
<span class="line"><span>fuzz/Cargo.lock</span></span></code></pre></div><p>Every one is an entry in <code>[tool.comply] ignore</code>: <code>.actrc</code>, <code>instructions.md</code>, <code>DCO.txt</code>, and the <code>**/*.lock</code> glob. <code>ignore</code> is a comply extension with no counterpart in the REUSE specification, so reuse walks them and comply does not. Expected, and the divergence disappears if the config is removed.</p><h3 id="fixed-three-files-only-comply-saw" tabindex="-1">Fixed: three files only comply saw <a class="header-anchor" href="#fixed-three-files-only-comply-saw" aria-label="Permalink to “Fixed: three files only comply saw”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LICENSES/Apache-2.0.txt</span></span>
<span class="line"><span>LICENSES/CC-BY-3.0.txt</span></span>
<span class="line"><span>LICENSES/MIT.txt</span></span></code></pre></div><p>The first read of this was wrong. It looked like symlink resolution -- the root holds three links into <code>LICENSES/</code> -- but <code>out_of_scope</code> already rejects symlinks. The cause was elsewhere.</p><p>The walk prunes <code>LICENSES/</code> as a <em>directory</em> and never descends, so the texts inside it never reach the seen-set. git tracks them all the same, and comply backfills tracked files the traversal dropped, because a gitignore rule must not hide a file git considers part of the project.</p><p>That backfill calls <code>out_of_scope</code> with <code>is_dir: false</code>, and the directory rule is guarded by exactly that flag:</p><div class="language-rust"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> is_dir </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> is_pruned_dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file_name) { </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }   </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// directories only</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">filter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> !</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">out_of_scope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(path, root, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))     </span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// backfill: is_dir = false</span></span></code></pre></div><p>So the one check that would have caught it was skipped, and the file came back. The sibling predicate <code>is_excluded</code> already had the component-wise check, with a comment naming this very hazard -- &quot;a named path was never descended into, so its ancestors have to be checked here&quot;. The backfill has the same property and did not use it.</p><p>The visible damage: comply asserted <code>LicenseInfoInFile: MIT OR Apache-2.0</code> for <code>LICENSES/MIT.txt</code> via the <code>**</code> aggregate, claiming the MIT licence text is itself covered by the project&#39;s dual licence.</p><p>Fixed by lifting the ancestor check into <code>scope::is_within_pruned_dir</code>, so the walk-time and named-path rules share one definition instead of two, and applying it in the backfill.</p><h3 id="comment-styles-a-superset-and-two-disagreements" tabindex="-1">Comment styles: a superset, and two disagreements <a class="header-anchor" href="#comment-styles-a-superset-and-two-disagreements" aria-label="Permalink to “Comment styles: a superset, and two disagreements”">​</a></h3><p>The extension and filename tables in <code>resources/comment-styles.toml</code> were captured from <code>reuse annotate</code> 6.2.0 and then extended. They are not identical to it. Every claim below was measured against reuse 6.2.0&#39;s <code>EXTENSION_COMMENT_STYLE_MAP</code> and confirmed by running <code>reuse annotate</code> on a file of each type.</p><p>comply claims 19 extensions reuse does not recognise at all:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ada cfg cmd conf cts dockerfile edn elm htm hxx</span></span>
<span class="line"><span>lhs makefile mts pas pm pp psd1 xhtml xslt</span></span></code></pre></div><p>and six filenames: <code>GNUmakefile</code>, <code>Vagrantfile</code>, <code>Brewfile</code>, <code>Podfile</code>, <code>.profile</code>, <code>.bash_profile</code>. A further sixteen extensions comply calls uncommentable are also unknown to reuse; those are counted in the &quot;Uncommentable formats&quot; table below rather than here.</p><p>None of these can make comply write a <em>wrong</em> header. reuse answers <code>None</code> and refuses the file, so the divergence is between &quot;annotated&quot; and &quot;refused&quot;, not between two syntaxes. <code>.mts</code>/<code>.cts</code> are the case that prompted the work -- refusing to annotate a TypeScript file because of its module suffix is a gap in that tool rather than a rule of the specification -- and <code>.cmd</code> is the same argument for a Windows script whose interpreter treats it exactly as <code>.bat</code>. Parity is owed on lint output, which never consults these tables.</p><p>Two extensions both tools claim get a different syntax:</p><table tabindex="0"><thead><tr><th>Extension</th><th>reuse 6.2.0</th><th>comply</th></tr></thead><tbody><tr><td><code>.c</code>, <code>.h</code></td><td><code>/*</code> <code>*</code> <code>*/</code> block</td><td><code>//</code> line</td></tr><tr><td><code>.ini</code></td><td><code>;</code></td><td><code>#</code></td></tr></tbody></table><p>reuse maps <code>.c</code> and <code>.h</code> to <code>CCommentStyle</code>, a bracketed block, while every other C-family extension it knows (<code>.cc</code>, <code>.cpp</code>, <code>.cxx</code>, <code>.hpp</code>) gets <code>//</code>. comply uses <code>//</code> throughout. Both are valid C and neither tool rewrites the other&#39;s header, but a tree annotated by both ends up carrying two shapes. <code>.ini</code> is the same class of thing: reuse writes <code>;</code>, comply writes <code>#</code>, and common INI parsers read both as comments.</p><p>Neither is being changed to match. They are recorded here so the claim that these tables agree with reuse is not made a third time.</p><p>Fortran (<code>.f90</code>, <code>.f95</code>, <code>.f03</code>, <code>.f08</code>, <code>!</code> line comments) and <code>.bat</code> (<code>REM</code> line comments) are not part of the superset -- reuse already annotates both, and comply&#39;s tables previously did not, which was a gap closed rather than a divergence introduced. <code>.svg</code> was a third disagreement until recently; see &quot;Uncommentable formats&quot; below.</p><p>More important is what the two now agree on. comply used to answer <code>Hash</code> for any extension no table claimed, so <code>.mts</code> was annotated <code>#</code> and the TypeScript stopped parsing; <code>.tsx</code>, <code>.jsx</code>, <code>.mjs</code>, <code>.cjs</code>, <code>.vue</code>, and <code>.lua</code> had the same defect. reuse refuses in exactly that case:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Error: The following files do not have a recognised file extension.</span></span>
<span class="line"><span>Please use &#39;--style&#39;, &#39;--force-dot-license&#39;, &#39;--fallback-dot-license&#39;,</span></span>
<span class="line"><span>or &#39;--skip-unrecognised&#39;</span></span></code></pre></div><p>comply now resolves an unclaimed name to <code>CommentStyle::Uncommentable</code>, which routes into the branch it already had for binaries -- warn, or honour <code>--skip-unrecognised</code> / <code>--force-dot-license</code>. A guess is never written.</p><p>The escape hatch differs. reuse takes <code>--style</code> per invocation; comply takes a <code>[[tool.comply.comment-styles]]</code> rule in the manifest, checked before the built-ins, so the declaration is committed once rather than repeated on every command. <code>hk.pkl</code> and <code>.gitmessage</code> in this repository are declared that way -- neither tool&#39;s built-ins claim them.</p><h3 id="uncommentable-formats-same-contract-different-tables" tabindex="-1">Uncommentable formats: same contract, different tables <a class="header-anchor" href="#uncommentable-formats-same-contract-different-tables" aria-label="Permalink to “Uncommentable formats: same contract, different tables”">​</a></h3><p>reuse splits what comply had merged. <code>UncommentableCommentStyle</code> marks a format that <em>has</em> no comment syntax -- 36 extensions and 14 filenames, <code>.png</code> and <code>.json</code> among them. Such a file gets a <code>.license</code> companion with no flag at all, and <code>--skip-unrecognised</code> does not reach it, because it was never unrecognised. An extension no table claims is a different thing entirely and is refused:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Error: The following files do not have a recognised file extension.</span></span>
<span class="line"><span>Please use &#39;--style&#39;, &#39;--force-dot-license&#39;, &#39;--fallback-dot-license&#39;,</span></span>
<span class="line"><span>or &#39;--skip-unrecognised&#39;</span></span></code></pre></div><p>comply resolves both to <code>CommentStyle::Uncommentable</code>, so <code>annotate</code> warned for both and wrote a companion for neither without <code>--force-dot-license</code>. A walked binary fared worse: the target loop kept only <code>FileType::Source</code>, so it was dropped before the branch could see it and the run said nothing at all.</p><p>The distinction reuse draws already existed here, one layer down -- <code>classify</code> in <code>file/classify.rs</code> calls exactly these formats <code>FileType::Binary</code>. <code>annotate</code> now consults it, which restores the contract without a second style variant. The companion carries no comment prefix on its lines:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SPDX-FileCopyrightText: 2026 X</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SPDX-License-Identifier: MIT</span></span></code></pre></div><p>On a genuine binary that is byte-for-byte what reuse writes, verified against a valid PNG. It is not byte-for-byte everywhere; see &quot;Line endings&quot; below.</p><p>What remains is table membership, not mechanism:</p><table tabindex="0"><thead><tr><th>Direction</th><th>Count</th><th>Examples</th></tr></thead><tbody><tr><td>Companion in comply, refused by reuse</td><td>20</td><td><code>.zip</code>, <code>.so</code>, <code>.exe</code>, <code>.ttf</code>, <code>.gz</code>, <code>.class</code></td></tr><tr><td>Companion in reuse, refused by comply</td><td>44</td><td><code>.csv</code>, <code>.webp</code>, <code>.xlsx</code>, <code>.ipynb</code>, <code>Cargo.lock</code>, <code>yarn.lock</code></td></tr><tr><td>Companion in both</td><td>6</td><td><code>.png</code>, <code>.jpg</code>, <code>.jpeg</code>, <code>.pdf</code>, <code>.json</code>, <code>.svg</code></td></tr></tbody></table><p>comply&#39;s list is the better call in the first row -- an object file or a zip archive plainly cannot carry a comment, and refusing to annotate one helps nobody. The second row is a genuine gap, and closing it means editing <code>is_binary_extension</code>, which also moves those files out of <code>lint</code>&#39;s inline-header expectation. That is a wider change than <code>annotate</code> and has not been made.</p><p><code>.svg</code> used to be the one entry in the third row the two treated differently: reuse wrote a companion, comply wrote an XML comment into the file. SVG does support a comment, but the inline writer prepends at byte 0, and an exported SVG opens with <code>&lt;?xml version=&quot;1.0&quot;?&gt;</code>, which XML requires to be the first thing in the document. The result was a file no parser accepts:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>logo.svg:7: parser error : XML declaration allowed only at the start of the</span></span>
<span class="line"><span>document</span></span></code></pre></div><p><code>lint</code> passed on it either way, so nothing downstream caught it. <code>.svg</code> now lives in the <code>[uncommentable]</code> table, which is what reuse answers and what <code>classify</code> already said, so the file is left alone and gets a companion.</p><p><code>.xml</code>, <code>.xhtml</code>, <code>.xsl</code> and <code>.xslt</code> are annotated in place by both tools, and the same defect reached them: comply prepended above the declaration, reuse did not. <code>preamble_lines</code> now treats <code>&lt;?xml</code> on line 1 the way it already treated <code>#!</code> and YAML frontmatter, so the two agree byte for byte:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?xml version=&quot;1.0&quot;?&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;!--</span></span>
<span class="line"><span>SPDX-FileCopyrightText: 2026 X</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SPDX-License-Identifier: MIT</span></span>
<span class="line"><span>--&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;root/&gt;</span></span></code></pre></div><h3 id="an-existing-companion-is-preserved-not-merged" tabindex="-1">An existing companion is preserved, not merged <a class="header-anchor" href="#an-existing-companion-is-preserved-not-merged" aria-label="Permalink to “An existing companion is preserved, not merged”">​</a></h3><p>Both tools leave the annotated file alone and act on the companion. They do not agree on what to do when one is already there. Given a <code>logo.png.license</code> reading <code>2019 Original Author</code> / <code>GPL-3.0-only</code>, and <code>annotate --copyright X --license MIT --year 2026</code>:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>reuse:   SPDX-FileCopyrightText: 2019 Original Author</span></span>
<span class="line"><span>         SPDX-FileCopyrightText: 2026 X</span></span>
<span class="line"><span></span></span>
<span class="line"><span>         SPDX-License-Identifier: GPL-3.0-only</span></span>
<span class="line"><span>         SPDX-License-Identifier: MIT          &lt;- merged</span></span>
<span class="line"><span></span></span>
<span class="line"><span>comply:  Unchanged (as .license): logo.png     &lt;- preserved, nothing written</span></span></code></pre></div><p>comply preserves and reports; <code>--force</code> replaces. That is the rule its inline path has always applied to a file that already carries a header, and <code>fix</code> applies the stronger form of it -- an existing companion is <code>Unchanged</code> there with no escape hatch at all. A third policy for the same artefact would be worse than the divergence.</p><p>Merging is the fuller answer and reuse&#39;s is the better output, but comply has no merge anywhere in it: unioning two SPDX expressions and de-duplicating copyright lines is a subsystem, not an edit, and it is not being invented under a bug fix. Open gap.</p><p>The severity is asymmetric, which is why the conservative side was taken. A missed merge is visible -- the run says <code>Unchanged</code> and the old notice is still there to read. The other direction erases a copyright holder&#39;s declaration silently, and <code>lint</code> passes on the result, so nothing downstream catches it.</p><h3 id="line-endings-mirrored-for-text-os-linesep-for-binaries" tabindex="-1">Line endings: mirrored for text, <code>os.linesep</code> for binaries <a class="header-anchor" href="#line-endings-mirrored-for-text-os-linesep-for-binaries" aria-label="Permalink to “Line endings: mirrored for text, os.linesep for binaries”">​</a></h3><p>reuse picks the companion&#39;s newline from the annotated file, but only when that file decodes as text (<code>cli/annotate.py</code>):</p><div class="language-python"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">encoding </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> detect_encoding(chunk)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">newline </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> detect_newline(chunk, </span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">encoding</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">encoding) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> encoding </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">is</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> not</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> None</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os.linesep</span></span></code></pre></div><p>A genuine binary returns <code>None</code> from <code>detect_encoding</code>, so <code>detect_newline</code> is never reached and the companion gets <code>os.linesep</code>. A real PNG signature does contain <code>\\r\\n</code>, but it never reaches the sniffer -- an 8-byte stub that decodes as text does, which is how this was first mis-read in the other direction.</p><p>comply always writes LF. Measured:</p><table tabindex="0"><thead><tr><th>Case</th><th>Result</th></tr></thead><tbody><tr><td>Valid PNG</td><td>identical (both LF on POSIX)</td></tr><tr><td>CRLF <code>.json</code></td><td>differs -- comply LF, reuse CRLF</td></tr><tr><td><code>--force-dot-license</code> over CRLF text</td><td>differs -- comply LF, reuse CRLF</td></tr></tbody></table><p><code>.json</code> is in comply&#39;s <code>FileType::Binary</code> set (<code>is_uncommentable_text_extension</code>), so the middle row sits on the default no-flag path rather than in a corner. On Windows the first row would differ too, since <code>os.linesep</code> is CRLF there.</p><h3 id="fix-and-annotate-now-write-the-same-companion" tabindex="-1"><code>fix</code> and <code>annotate</code> now write the same companion <a class="header-anchor" href="#fix-and-annotate-now-write-the-same-companion" aria-label="Permalink to “fix and annotate now write the same companion”">​</a></h3><p>Closed. <code>fix_binary_file</code> (<code>crates/comply/src/fix.rs</code>) now calls <code>header::generate</code> instead of hand-rolling the two tags with <code>format!</code> -- the same generator <code>annotate</code>&#39;s Uncommentable branch reaches through <code>generate_with</code>. The missing blank line between the tags is gone, and there is now exactly one construction of companion content in the codebase.</p><p>Verified against reuse 6.2.0 with a genuine PNG (valid IHDR/IDAT/IEND, not a short stub -- reuse&#39;s encoding detection reads a short file as text and mirrors its newline convention, which would have hidden the CRLF question rather than answering it): <code>reuse annotate</code>, <code>comply fix</code>, and <code>comply annotate</code> all wrote the identical 61-byte companion:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SPDX-FileCopyrightText: 2026 X</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SPDX-License-Identifier: MIT</span></span></code></pre></div><p><code>crates/comply/src/cli/commands/fix.rs</code>&#39;s <code>fix_and_annotate_write_byte_identical_companions</code> test pins the two commands to each other so this cannot drift again.</p><h3 id="representation-one-expression-or-one-line-per-identifier" tabindex="-1">Representation: one expression, or one line per identifier <a class="header-anchor" href="#representation-one-expression-or-one-line-per-identifier" aria-label="Permalink to “Representation: one expression, or one line per identifier”">​</a></h3><p>For a file licensed <code>MIT OR Apache-2.0</code>, the two tools write the same fact differently:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>comply:  LicenseInfoInFile: MIT OR Apache-2.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>reuse:   LicenseInfoInFile: Apache-2.0</span></span>
<span class="line"><span>         LicenseInfoInFile: Apache-2.0</span></span>
<span class="line"><span>         LicenseInfoInFile: MIT</span></span>
<span class="line"><span>         LicenseInfoInFile: MIT</span></span></code></pre></div><p>The identifier sets are identical, so no information differs. Worth noting on both sides: <code>LicenseInfoInFile</code> is a repeatable field whose values are individual licence identifiers, which favours reuse&#39;s shape -- but reuse emits each identifier twice, which is its own quirk. Neither is checked by any gate today.</p><h2 id="deliberate-divergences-unchanged" tabindex="-1">Deliberate divergences, unchanged <a class="header-anchor" href="#deliberate-divergences-unchanged" aria-label="Permalink to “Deliberate divergences, unchanged”">​</a></h2><p>These are recorded in <code>docs/plan/IMPLEMENTATION.md</code> so they are not mistaken for drift:</p><ul><li><strong>Checksums.</strong> comply emits <code>SHA256</code> alongside the spec-required <code>SHA1</code>; SHA-1 alone is no longer fit for integrity claims.</li><li><strong>Document namespace.</strong> Derived from the file set rather than a random UUID, so an unchanged tree yields a byte-identical document and two SBOMs can be diffed in review.</li><li><strong>Skipped files.</strong> Omitted from the SBOM rather than listed as <code>NOASSERTION</code>, which would assert &quot;unknown&quot; about a file the manifest covers. The SBOM&#39;s file count now equals the number <code>lint</code> reports checked.</li></ul><h2 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to “Method”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &amp;&amp;  </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">comply</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spdx</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">      # comply 0.1.0, built from the workspace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reuse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &amp;&amp;  </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reuse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  spdx</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">      # reuse 6.2.0, via mise x pipx:reuse@6.2.0</span></span></code></pre></div><p>File sets extracted from each SBOM&#39;s <code>FileName:</code> records and compared with <code>comm</code>; per-file licensing compared as SPDX identifier sets, which normalises away the representation difference above.</p><p>reuse is not installed, invoked or checked by any task, workflow or hook in this project. comply is the tool of record; this comparison is a one-off differential check, run on request to validate comply against the specification rather than to gate anything.</p><h2 id="run-data" tabindex="-1">Run data <a class="header-anchor" href="#run-data" aria-label="Permalink to “Run data”">​</a></h2><p>Generated from a live run over the comply repository.</p><ul><li>comply <code>lint</code>: 110 total, 109 passed, 0 failed, 1 skipped, exit 0.</li><li>reuse <code>lint</code>: 116 / 116 files with copyright and licence information, exit 0.</li></ul><p>The 7-file gap is comply&#39;s <code>ignore</code> config; every file both tools see agrees on licensing.</p>`,88)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};